param(
    [string]$ProjectRoot = "",
    [switch]$SkipInitialBuild,
    [switch]$SkipFinalBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$ExpectedSha = "3821A0371A77C824929B735239A7AD2A2C599B2682B8E47ED3EFD7DD3FD44BC4"
$DesiredSha = "E4C9D5DAB8B2933C7BBD2216E1CAD110D2A291F55400D57FB7B86A9D66D3BD43"
$MarkerOld = "ORCALY_ORDER_WHATSAPP_MESSAGE_V1"
$MarkerNew = "ORCALY_ORDER_WHATSAPP_UNICODE_V2"

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $ProjectRoot = (Get-Location).Path
} else {
    $ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
}

$Target = Join-Path $ProjectRoot "lib\order-whatsapp.ts"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\whatsapp-unicode-" + $Timestamp)
$BackupFile = Join-Path $BackupRoot "lib\order-whatsapp.ts"

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function Sha([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return ""
    }

    return (
        Get-FileHash -LiteralPath $Path -Algorithm SHA256
    ).Hash.ToUpperInvariant()
}

function Restore {
    if (Test-Path -LiteralPath $BackupFile -PathType Leaf) {
        Copy-Item -LiteralPath $BackupFile -Destination $Target -Force
        Warn "Rollback concluido: lib/order-whatsapp.ts restaurado."
    }
}

try {
    Write-Host ""
    Write-Host "ORCALY - WHATSAPP UNICODE V2" -ForegroundColor Cyan
    Write-Host "Emojis seguros para Windows, Git, URL e WhatsApp." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot "package.json") -PathType Leaf)) {
        throw "Execute este script na raiz do projeto Orcaly."
    }

    Set-Location $ProjectRoot

    if (-not (Test-Path -LiteralPath $Target -PathType Leaf)) {
        throw "lib/order-whatsapp.ts nao existe. A melhoria anterior precisa estar aplicada."
    }

    $currentText = [IO.File]::ReadAllText($Target)

    if (-not $currentText.Contains($MarkerOld)) {
        throw "O gerador WhatsApp atual nao possui o marcador esperado."
    }

    if ($currentText.Contains($MarkerNew)) {
        Ok "A correcao Unicode ja esta aplicada."
        exit 0
    }

    $currentSha = Sha $Target

    if ($currentSha -ne $ExpectedSha) {
        throw (
            "lib/order-whatsapp.ts mudou desde a versao auditada. " +
            "O script recusou sobrescrever. SHA atual: " +
            $currentSha
        )
    }

    Ok "Gerador WhatsApp corresponde exatamente a versao V3 auditada."

    if (-not $SkipInitialBuild) {
        Step "Build inicial"
        & npm.cmd run build

        if ($LASTEXITCODE -ne 0) {
            throw "O projeto ja falha no build antes desta correcao. Nada foi alterado."
        }

        Ok "Build inicial passou."
    }

    Step "Criando backup"

    [IO.Directory]::CreateDirectory((Split-Path -Parent $BackupFile)) | Out-Null
    Copy-Item -LiteralPath $Target -Destination $BackupFile -Force
    Ok ("Backup: " + $BackupFile)

    Step "Aplicando Unicode seguro"

    $bytes = [Convert]::FromBase64String("")
    $content = [Text.Encoding]::UTF8.GetString($bytes)
    [IO.File]::WriteAllText($Target, $content, $Utf8NoBom)

    if ((Sha $Target) -ne $DesiredSha) {
        throw "O arquivo gravado nao corresponde ao conteudo validado."
    }

    $after = [IO.File]::ReadAllText($Target)

    if (-not $after.Contains($MarkerNew)) {
        throw "Marcador Unicode nao encontrado."
    }

    if (-not $after.Contains('\u{1F4E6} *PEDIDO #')) {
        throw "Emoji do pedido nao foi convertido para escape Unicode."
    }

    if (-not $after.Contains('\u{1F4B5} *TOTAL DO PEDIDO:*')) {
        throw "Emoji do total nao foi convertido para escape Unicode."
    }

    if (-not $after.Contains('\u{1F60A}')) {
        throw "Emoji final nao foi convertido para escape Unicode."
    }

    Ok "Todos os emojis da mensagem agora sao gerados por escapes Unicode."

    Step "Lint"
    & npx.cmd eslint "lib/order-whatsapp.ts"

    if ($LASTEXITCODE -ne 0) {
        throw "O gerador WhatsApp falhou no lint."
    }

    Ok "Lint passou."

    if (-not $SkipFinalBuild) {
        Step "Build final"
        & npm.cmd run build

        if ($LASTEXITCODE -ne 0) {
            throw "O build final falhou apos a correcao Unicode."
        }

        Ok "Build final passou."
    }

    Step "Resumo"

    Write-Host ""
    Write-Host "WHATSAPP UNICODE CORRIGIDO" -ForegroundColor Green
    Write-Host ""
    Write-Host " - emojis literais removidos do codigo-fonte"
    Write-Host " - emojis reconstruidos por Unicode no navegador"
    Write-Host " - encodeURIComponent continua protegendo a URL wa.me"
    Write-Host " - mensagem e dados do pedido foram preservados"
    Write-Host " - nenhum banco, checkout ou API foi alterado"
    Write-Host ""
    Write-Host "Teste agora em /painel/pedidos."
    Write-Host ""
    Write-Host "Nenhum commit, push ou deploy foi executado." -ForegroundColor Cyan
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if (Test-Path -LiteralPath $BackupFile -PathType Leaf) {
        Restore
    }

    Write-Host ("Backup/diagnostico: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
